import re
from collections import Counter

anagram_text = "Our brooding Dane in Elsinore weighs noble minds suffering, pondering slings and arrows, and questions of being, while outrageous fortune turns against him."

def normalize(s):
    return re.sub(r'[^a-z]', '', s.lower())

an_letters = normalize(anagram_text)

candidates = [
    "To be or not to be that is the question",
    "Whether tis nobler in the mind to suffer the slings and arrows of outrageous fortune",
    "To be or not to be that is the question whether tis nobler in the mind to suffer the slings and arrows of outrageous fortune"
]

for line in candidates:
    if Counter(an_letters) == Counter(normalize(line)):
        print("Match:", line)
